module AnthonyCoraGame(\n    input wire clk,\n    input wire rst_n,\n    input wire start,\n    input wire [3:0] N,\n    input wire [3:0] M,\n    input wire [31:0] p_in,\n    input wire p_valid,\n    output reg [31:0] result,\n    output reg done,\n    output reg error\n);\n\n    // State declarations\n    localparam [1:0] IDLE    = 2'd0;\n    localparam [1:0] LOAD    = 2'd1;\n    localparam [1:0] COMPUTE = 2'd2;\n    localparam [1:0] FINISH  = 2'd3;\n    reg [1:0] state, next_state;\n\n    // DP table (17x17 Q16.16 values)\n    reg [31:0] dp [0:16][0:16];\n    \n    // Computation control\n    reg [31:0] p_reg;\n    reg [4:0] current_round;\n    reg [4:0] i;\n    reg [5:0] load_counter;\n    reg [9:0] cycle_count;\n    wire [4:0] max_round;\n    reg error_reg;\n\n    // Max iterations = N+M-1 (N/M <= 16)\n    assign max_round = N + M;  // Will compare <= max_round, +1 equals N+M\n\n    // Synthesis-friendly Q16.16 multipliers\n    wire [63:0] product1_comb, product2_comb;\n    assign product1_comb = p_reg * dp[i][max_round - i - 1];\n    assign product2_comb = (32'h10000 - p_reg) * dp[i-1][max_round - i];\n    \n    // Main state machine\n    always @(posedge clk or negedge rst_n) begin\n        integer j;\n        reg [3:0] base_i, base_j;\n\n        if (!rst_n) begin\n            state <= IDLE;\n            done <= 1'b0;\n            error_reg <= 1'b0;\n            cycle_count <= 10'd0;\n            load_counter <= 6'd0;\n            result <= 32'd0;\n            p_reg <= 32'd0;\n\n            // Initialize dp array\n            for (base_i = 0; base_i <= 4'd16; base_i = base_i + 1) begin\n                for (base_j = 0; base_j <= 4'd16; base_j = base_j + 1) begin\n                    dp[base_i][base_j] <= 32'd0;\n                end\n            end\n        end else begin\n            state <= next_state;\n            cycle_count <= cycle_count + 1;\n\n            case (state)\n                IDLE: begin\n                    done <= 1'b0;\n                    error_reg <= 1'b0;\n                    cycle_count <= 10'd0;\n                    if (start) begin\n                        if (p_valid) p_reg <= p_in;\n                        \n                        // Input validation\n                        if ((N < 4'd1) || (N > 4'd15) || (M < 4'd1) || (M > 4'd15)) begin\n                            error_reg <= 1'b1;\n                            next_state <= FINISH;\n                        end else begin\n                            load_counter <= 6'd0;\n                            next_state <= LOAD;\n                        end\n                    end else begin\n                        next_state <= IDLE;\n                    end\n                end\n\n                LOAD: begin\n                    // Initialize base cases\n                    if (load_counter < 6'd33) begin\n                        if (load_counter < 6'd16) begin\n                            // dp[i][0] = 0 for i >= 1\n                            dp[load_counter + 1][0] <= 32'd0;\n                        end else if (load_counter < 6'd32) begin\n                            // dp[0][j] = 1 for j >= 1\n                            dp[0][load_counter - 15] <= 32'h10000;\n                        end\n                        load_counter <= load_counter + 1;\n                        next_state <= LOAD;\n                    end else begin\n                        current_round <= 5'd2;\n                        i <= 5'd1;\n                        next_state <= COMPUTE;\n                    end\n                end\n\n                COMPUTE: begin\n                    // Timeout handling\n                    if (cycle_count >= 10'd1000) begin\n                        error_reg <= 1'b1;\n                        next_state <= FINISH;\n                    end else if (current_round < max_round) begin\n                        // Compute dp[i][current_round - i]\n                        j = current_round - i;\n\n                        if ((i <= N) && (j <= M) && (j >= 1)) begin\n                            dp[i][j] <= product1_comb[47:16] + product2_comb[47:16];\n                        end\n                        \n                        if (i == N || j <= 1) begin\n                            current_round <= current_round + 1;\n                            i <= 5'd1;\n                        end else begin\n                            i <= i + 1;\n                        end\n                        next_state <= COMPUTE;\n                    end else begin\n                        next_state <= FINISH;\n                    end\n                end\n\n                FINISH: begin\n                    result <= dp[N][M];\n                    done <= 1'b1;\n                    error <= error_reg;\n                    next_state <= IDLE;\n                end\n\n                default: next_state <= IDLE;\n            endcase\n        end\n    end\n\nendmodule